mapper.select:
select record_id
from event_acks
where user_id = #{userId}
  and house_id = #{houseId}
  and category = #{category}
  and (
      action in ('ack', 'ignore')
      or (action = 'snooze' and snooze_until is not null and snooze_until > #{now})
  )

select '生产' as category,
       coalesce(sum(case when production_ack.action = 'ack' then 1 else 0 end), 0) as ackCount,
       coalesce(sum(case when production_ack.action = 'ignore' then 1 else 0 end), 0) as ignoreCount,
       coalesce(sum(case when production_ack.action = 'snooze' then 1 else 0 end), 0) as snoozeCount,
       avg(case when production_ack.action = 'ack'
           then timestampdiff(minute, production_ack.event_date, production_ack.ack_time) / 60.0 end) as avgHandleHours
from (
    select ea.action, ea.ack_time, br.next_event_date as event_date
    from event_acks ea
    inner join batch_rabbits br on br.id = ea.record_id
    inner join batches b on b.id = br.batch_id
    where ea.house_id = #{houseId}
      and ea.category = '生产'
      and b.house_id = #{houseId}

        and ea.ack_time >= #{from}


        and ea.ack_time <= #{to}

    union all
    select ea.action, ea.ack_time, bc.next_event_date as event_date
    from event_acks ea
    inner join breeding_cycles bc on bc.id = ea.record_id
        and bc.house_id = ea.house_id
    where ea.house_id = #{houseId}
      and ea.category = '生产周期'

        and ea.ack_time >= #{from}


        and ea.ack_time <= #{to}

) production_ack

select '后备成熟' as category,
       sum(case when ea.action = 'ack' then 1 else 0 end) as ackCount,
       sum(case when ea.action = 'ignore' then 1 else 0 end) as ignoreCount,
       sum(case when ea.action = 'snooze' then 1 else 0 end) as snoozeCount,
       avg(case when ea.action = 'ack' then timestampdiff(minute, rr.expected_mature_date, ea.ack_time) / 60.0 end) as avgHandleHours
from event_acks ea
join replacement_records rr on rr.id = ea.record_id
where ea.house_id = #{houseId}
  and ea.category = '后备成熟'
  and rr.house_id = #{houseId}

    and ea.ack_time >= #{from}


    and ea.ack_time <= #{to}
